#include <bits/stdc++.h>
using namespace std;

int diff(int x, int y) {
    int z = x - y;
    if (z >= 0) return z;
    return z * (-1);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    map<char, int> m;
    char c = 'a';
    for (int i = 1; i <= 26; i++) {
        m[c] = i;
        c++;
    }

    string s;
    cin >> s;
    int ans = 0;

    for (int i = 0; i < s.length(); i++) {
        int a, b;
        if (i == 0) {
            a = diff(m[s[i]], m['a']);
            b = diff(a, 26);
        } else {
            a = diff(m[s[i]], m[s[i-1]]);
            b = diff(a, 26);
        }
        if (a < b) ans += a;
        else ans += b;
    }

    cout << ans << "\n";
    return 0;
}

